import { readFileSync } from 'node:fs';
import vm from 'node:vm';

const APP_URL = new URL('../../public/app.js', import.meta.url);

function textNode(data) {
  return { nodeType: 3, data: String(data) };
}

function toNodes(items) {
  return items.map((item) => (typeof item === 'string' ? textNode(item) : item));
}

function nodeText(node) {
  return node.nodeType === 3 ? node.data : node.textContent;
}

export class FakeElement {
  constructor(tagName, id = '') {
    this.nodeType = 1;
    this.tagName = tagName.toUpperCase();
    this.id = id;
    this.type = '';
    this.disabled = false;
    this.childNodes = [];
    this.listeners = {};
    this.rawValue = undefined;
  }

  get value() {
    if (this.rawValue !== undefined) return this.rawValue;
    if (this.tagName === 'SELECT') {
      const first = this.childNodes.find((n) => n.tagName === 'OPTION');
      return first ? first.value : '';
    }
    return '';
  }

  set value(v) {
    this.rawValue = String(v);
  }

  get textContent() {
    return this.childNodes.map(nodeText).join('');
  }

  set textContent(text) {
    const s = String(text);
    this.childNodes = s === '' ? [] : [textNode(s)];
  }

  append(...nodes) {
    this.childNodes = this.childNodes.concat(toNodes(nodes));
  }

  replaceChildren(...nodes) {
    this.childNodes = toNodes(nodes);
  }

  addEventListener(type, fn) {
    (this.listeners[type] ||= []).push(fn);
  }

  dispatch(type) {
    const event = {
      type,
      defaultPrevented: false,
      preventDefault() { this.defaultPrevented = true; },
    };
    for (const fn of this.listeners[type] || []) fn(event);
    return event;
  }
}

const SPECS = [
  ['booking-form', 'form'], ['room', 'select'], ['title', 'input', 'text'],
  ['date', 'input', 'date'], ['start', 'input', 'time'], ['end', 'input', 'time'],
  ['book', 'button', 'submit', 'Book'], ['filter-date', 'input', 'date'],
  ['show-all', 'button', 'button'], ['booking-list', 'ul'], ['error', 'p'],
];

function buildElements() {
  const byId = new Map();
  for (const [id, tag, type, text] of SPECS) {
    const e = new FakeElement(tag, id);
    if (type) e.type = type;
    if (text) e.textContent = text;
    byId.set(id, e);
  }
  return byId;
}

function buildDocument(byId) {
  const document = Object.create(null);
  document.getElementById = (id) => byId.get(id) ?? null;
  document.createElement = (tag) => new FakeElement(tag);
  return document;
}

function makeControlledFetch(calls) {
  return (url, options) => new Promise((resolve, reject) => {
    const call = {
      url, options, jsonCalls: 0,
      resolveWith: (response) => resolve(response),
      resolve(status, body) {
        resolve({ status, json: () => { call.jsonCalls += 1; return Promise.resolve(body); } });
      },
      resolveBadJson(status) {
        resolve({
          status,
          json: () => { call.jsonCalls += 1; return Promise.reject(new SyntaxError('bad json')); },
        });
      },
      reject() { reject(new TypeError('fetch failed')); },
    };
    calls.push(call);
  });
}

async function flush(turns = 5) {
  for (let i = 0; i < turns; i += 1) await new Promise((r) => setImmediate(r));
}

export function loadPage({ fetchImpl } = {}) {
  const calls = [];
  const byId = buildElements();
  const document = buildDocument(byId);
  const fetch = fetchImpl ?? makeControlledFetch(calls);
  const source = readFileSync(APP_URL, 'utf8');
  const context = vm.createContext({ document, fetch });
  vm.runInContext(source, context, { filename: 'app.js' });
  return { document, el: (id) => byId.get(id), calls, flush };
}

function summarizeNode(node) {
  if (node.nodeType === 3) return { text: node.data };
  return { tag: node.tagName, type: node.type, text: node.textContent, disabled: node.disabled };
}

export function listTexts(ul) {
  return ul.childNodes.map((li) => {
    const [first, second] = li.childNodes;
    return {
      text: first && first.nodeType === 3 ? first.data : undefined,
      button: second && second.tagName === 'BUTTON'
        ? { type: second.type, text: second.textContent, disabled: second.disabled }
        : undefined,
      childCount: li.childNodes.length,
      nodes: li.childNodes.map(summarizeNode),
    };
  });
}
import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import { loadPage } from './helpers/fake-dom.mjs';

const NO_REPLY = 'Could not reach the server.';
const FAILED = 'Request failed.';
const ROOMS = { rooms: ['Aurora', 'Borealis', 'Cosmos'] };
const BOOKING = { id: 9, room: 'Cosmos', title: 'Team sync', date: '2026-11-03', start: '09:00', end: '10:00' };
const OTHER = { id: 8, room: 'Aurora', title: 'Other', date: '2026-11-03', start: '11:00', end: '12:00' };
const SEVEN = { ...OTHER, id: 7, title: 'Seven' };

const methodOf = (call) => call.options?.method ?? 'GET';
const plain = (x) => JSON.parse(JSON.stringify(x));

async function boot(list = []) {
  const page = loadPage();
  page.calls[0].resolve(200, ROOMS);
  page.calls[1].resolve(200, { bookings: list });
  await page.flush();
  return page;
}

function fillForm(el) {
  el('room').value = 'Cosmos';
  el('title').value = '  Team sync  ';
  el('date').value = '2026-11-03';
  el('start').value = '09:00';
  el('end').value = '10:00';
}

// A fetch whose calls are controllable and which runs hook(call) at start.
function hookedFetch(hook) {
  const calls = [];
  const fetchImpl = (url, options) => new Promise((resolve, reject) => {
    const call = {
      url, options,
      resolve: (status, body) => resolve({ status, json: () => Promise.resolve(body) }),
      reject: () => reject(new TypeError('fetch failed')),
    };
    calls.push(call);
    hook(call);
  });
  return { calls, fetchImpl };
}

async function bootHooked(hook, list = []) {
  const { calls, fetchImpl } = hookedFetch(hook);
  const page = loadPage({ fetchImpl });
  calls[0].resolve(200, ROOMS);
  calls[1].resolve(200, { bookings: list });
  await page.flush();
  return { ...page, calls };
}

const cancelButton = (el, i = 0) => el('booking-list').childNodes[i].childNodes[1];

describe('submit', () => {
  test('sends POST with raw values, disables Book, prevents default', async () => {
    const { calls, el } = await boot();
    fillForm(el);
    const ev = el('booking-form').dispatch('submit');
    assert.equal(ev.defaultPrevented, true);
    assert.equal(el('book').disabled, true);
    assert.equal(calls.length, 3);
    const call = calls[2];
    assert.equal(call.url, '/api/bookings');
    assert.equal(call.options.method, 'POST');
    assert.deepEqual(plain(call.options.headers), { 'Content-Type': 'application/json' });
    assert.deepEqual(JSON.parse(call.options.body), {
      room: 'Cosmos', title: '  Team sync  ', date: '2026-11-03', start: '09:00', end: '10:00',
    });
  });

  test('no client-side checks: empty fields still POST', async () => {
    const page = loadPage();
    page.calls[1].resolve(200, { bookings: [] });
    await page.flush();
    page.el('booking-form').dispatch('submit');
    assert.equal(page.calls.length, 3);
    assert.equal(methodOf(page.calls[2]), 'POST');
    assert.deepEqual(JSON.parse(page.calls[2].options.body),
      { room: '', title: '', date: '', start: '', end: '' });
  });

  test('second submit while the first is pending sends nothing', async () => {
    const { calls, el } = await boot();
    el('booking-form').dispatch('submit');
    const ev = el('booking-form').dispatch('submit');
    assert.equal(ev.defaultPrevented, true);
    assert.equal(calls.length, 3);
  });

  test('submit with Book disabled sends nothing', async () => {
    const { calls, el } = await boot();
    el('book').disabled = true;
    const ev = el('booking-form').dispatch('submit');
    assert.equal(ev.defaultPrevented, true);
    assert.equal(calls.length, 2);
  });
});

describe('submit outcomes', () => {
  const successCases = [
    ['no filter', '', '/api/bookings'],
    ['filter set', '2026-11-03', '/api/bookings?date=2026-11-03'],
  ];
  for (const [name, filter, url] of successCases) {
    test(`201 resets title, clears error, refetches list (${name})`, async () => {
      const { calls, el, flush } = await boot();
      fillForm(el);
      el('filter-date').value = filter;
      el('error').textContent = 'old';
      el('booking-form').dispatch('submit');
      calls[2].resolve(201, BOOKING);
      await flush();
      assert.equal(el('book').disabled, false);
      assert.equal(el('title').value, '');
      assert.equal(el('room').value, 'Cosmos');
      assert.equal(el('date').value, '2026-11-03');
      assert.equal(el('start').value, '09:00');
      assert.equal(el('end').value, '10:00');
      assert.equal(el('error').textContent, '');
      assert.equal(calls.length, 4);
      assert.equal(calls[3].url, url);
      assert.equal(methodOf(calls[3]), 'GET');
    });
  }

  const errorCases = [
    ['409 with message', 409, { error: 'room is already booked from 09:00 to 10:00' },
      'room is already booked from 09:00 to 10:00'],
    ['400 without message', 400, {}, FAILED],
    ['500 with non-string error', 500, { error: ['x'] }, FAILED],
    ['200 is not the POST success status', 200, {}, FAILED],
  ];
  for (const [name, status, body, message] of errorCases) {
    test(`error status: ${name}`, async () => {
      const { calls, el, flush } = await boot();
      fillForm(el);
      el('booking-form').dispatch('submit');
      calls[2].resolve(status, body);
      await flush();
      assert.equal(el('error').textContent, message);
      assert.equal(el('title').value, '  Team sync  ');
      assert.equal(calls.length, 3);
      assert.equal(el('book').disabled, false);
    });
  }

  const noReply = [
    ['reject', (c) => c.reject()],
    ['bad json on 201', (c) => c.resolveBadJson(201)],
  ];
  for (const [name, act] of noReply) {
    test(`no reply: ${name}`, async () => {
      const { calls, el, flush } = await boot();
      fillForm(el);
      el('booking-form').dispatch('submit');
      act(calls[2]);
      await flush();
      assert.equal(el('error').textContent, NO_REPLY);
      assert.equal(el('title').value, '  Team sync  ');
      assert.equal(calls.length, 3);
      assert.equal(el('book').disabled, false);
    });
  }
});

describe('Book re-enabled as soon as the request settles', () => {
  test('stays disabled until the body has arrived', async () => {
    const { calls, el, flush } = await boot();
    let release;
    const p = new Promise((r) => { release = r; });
    el('booking-form').dispatch('submit');
    calls[2].resolveWith({ status: 201, json: () => p });
    await flush();
    assert.equal(el('book').disabled, true);
    release(BOOKING);
    await flush();
    assert.equal(el('book').disabled, false);
  });

  test('enabled before the list refetch starts', async () => {
    const seen = [];
    let book;
    const page = await bootHooked((call) => {
      if (call.options?.method === 'GET' && call.url === '/api/bookings') {
        seen.push(book.disabled);
      }
    });
    book = page.el('book');
    seen.length = 0;
    page.el('booking-form').dispatch('submit');
    page.calls[2].resolve(201, BOOKING);
    await page.flush();
    assert.deepEqual(seen, [false]);
  });

  test('enabled before #error is set on an error status', async () => {
    const { calls, el, flush } = await boot();
    const errorEl = el('error');
    const seen = [];
    let stored = '';
    Object.defineProperty(errorEl, 'textContent', {
      get() { return stored; },
      set(v) { seen.push(el('book').disabled); stored = v; },
    });
    el('booking-form').dispatch('submit');
    calls[2].resolve(409, { error: 'nope' });
    await flush();
    assert.deepEqual(seen, [false]);
    assert.equal(stored, 'nope');
  });
});

describe('cancel', () => {
  test('click disables the button and sends DELETE', async () => {
    const { calls, el } = await boot([SEVEN, OTHER]);
    const btn = cancelButton(el, 0);
    btn.dispatch('click');
    assert.equal(btn.disabled, true);
    assert.equal(calls.length, 3);
    assert.equal(calls[2].url, '/api/bookings/7');
    assert.equal(calls[2].options.method, 'DELETE');
  });

  test('204 enables button, clears error, refetches once, no json()', async () => {
    const { calls, el, flush } = await boot([SEVEN, OTHER]);
    el('error').textContent = 'old';
    const btn = cancelButton(el, 0);
    btn.dispatch('click');
    calls[2].resolve(204);
    await flush();
    assert.equal(btn.disabled, false);
    assert.equal(el('error').textContent, '');
    assert.equal(calls.length, 4);
    assert.equal(calls[3].url, '/api/bookings');
    assert.equal(methodOf(calls[3]), 'GET');
    assert.equal(calls[2].jsonCalls, 0);
  });

  const statusCases = [
    ['404 with message', 404, { error: 'booking not found' }, 'booking not found'],
    ['500 with string body', 500, 'x', FAILED],
  ];
  for (const [name, status, body, message] of statusCases) {
    test(`error status ${name} still refetches the list`, async () => {
      const { calls, el, flush } = await boot([SEVEN]);
      const btn = cancelButton(el, 0);
      btn.dispatch('click');
      calls[2].resolve(status, body);
      await flush();
      assert.equal(el('error').textContent, message);
      assert.equal(btn.disabled, false);
      assert.equal(calls.length, 4);
      assert.equal(calls[3].url, '/api/bookings');
    });
  }

  test('no reply shows message, enables button, no refetch', async () => {
    const { calls, el, flush } = await boot([SEVEN]);
    const btn = cancelButton(el, 0);
    btn.dispatch('click');
    calls[2].reject();
    await flush();
    assert.equal(el('error').textContent, NO_REPLY);
    assert.equal(btn.disabled, false);
    assert.equal(calls.length, 3);
  });

  test('button enabled before the list refetch starts', async () => {
    const seen = [];
    let btn;
    const page = await bootHooked((call) => {
      if (call.options?.method === 'GET' && btn) seen.push(btn.disabled);
    }, [SEVEN]);
    btn = cancelButton(page.el, 0);
    btn.dispatch('click');
    page.calls[2].resolve(204);
    await page.flush();
    assert.deepEqual(seen, [false]);
  });

  test('button enabled before #error is set', async () => {
    const { calls, el, flush } = await boot([SEVEN]);
    const btn = cancelButton(el, 0);
    const seen = [];
    let stored = '';
    Object.defineProperty(el('error'), 'textContent', {
      get() { return stored; },
      set(v) { seen.push(btn.disabled); stored = v; },
    });
    btn.dispatch('click');
    calls[2].resolve(404, { error: 'booking not found' });
    await flush();
    assert.deepEqual(seen, [false]);
  });

  test('list refetch after cancel honours the filter', async () => {
    const { calls, el, flush } = await boot([SEVEN]);
    el('filter-date').value = '2026-11-04';
    cancelButton(el, 0).dispatch('click');
    calls[2].resolve(204);
    await flush();
    assert.equal(calls[3].url, '/api/bookings?date=2026-11-04');
  });
});

import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import { loadPage, listTexts } from './helpers/fake-dom.mjs';

const NO_REPLY = 'Could not reach the server.';
const FAILED = 'Request failed.';

const methodOf = (call) => call.options?.method ?? 'GET';

const B1 = { id: 2, room: 'Cosmos', title: 'Standup', date: '2026-11-04', start: '09:00', end: '10:00' };
const B2 = { id: 1, room: 'Aurora', title: '<b>x</b>', date: '2026-11-03', start: '13:00', end: '14:30' };
const X = { id: 5, room: 'Borealis', title: 'Xray', date: '2026-11-05', start: '08:00', end: '09:00' };
const Y = { id: 6, room: 'Aurora', title: 'Yankee', date: '2026-11-06', start: '10:00', end: '11:00' };
const X_TEXT = '2026-11-05 08:00-09:00 Borealis: Xray';

const texts = (page) => listTexts(page.el('booking-list')).map((r) => r.text);

async function changeFilter(page, value) {
  page.el('filter-date').value = value;
  page.el('filter-date').dispatch('change');
  await page.flush();
}

describe('initial requests', () => {
  test('rooms and list fetches both start synchronously', () => {
    const { calls } = loadPage();
    assert.equal(calls.length, 2);
    assert.equal(calls[0].url, '/api/rooms');
    assert.equal(methodOf(calls[0]), 'GET');
    assert.equal(calls[1].url, '/api/bookings');
    assert.equal(methodOf(calls[1]), 'GET');
  });
});

describe('rooms', () => {
  test('fills #room with one option per room', async () => {
    const { calls, el, flush } = loadPage();
    const rooms = ['Aurora', 'Borealis', 'Cosmos'];
    calls[0].resolve(200, { rooms });
    await flush();
    const nodes = el('room').childNodes;
    assert.equal(nodes.length, 3);
    nodes.forEach((n, i) => {
      assert.equal(n.tagName, 'OPTION');
      assert.equal(n.value, rooms[i]);
      assert.equal(n.textContent, rooms[i]);
    });
    assert.equal(el('error').textContent, '');
  });

  const statusCases = [
    ['500 with error string', 500, { error: 'boom' }, 'boom'],
    ['404 with non-string error', 404, { error: 5 }, FAILED],
    ['500 with array body', 500, [], FAILED],
    ['500 with string body', 500, 'text', FAILED],
    ['500 with null body', 500, null, FAILED],
    ['201 for a GET', 201, { rooms: ['Aurora'] }, FAILED],
  ];
  for (const [name, status, body, message] of statusCases) {
    test(`error status: ${name}`, async () => {
      const { calls, el, flush } = loadPage();
      calls[0].resolve(status, body);
      await flush();
      assert.equal(el('error').textContent, message);
      assert.equal(el('room').childNodes.length, 0);
    });
  }

  const noReply = [
    ['reject', (c) => c.reject()],
    ['bad json on 200', (c) => c.resolveBadJson(200)],
    ['bad json on 500', (c) => c.resolveBadJson(500)],
  ];
  for (const [name, act] of noReply) {
    test(`no reply: ${name}`, async () => {
      const { calls, el, flush } = loadPage();
      act(calls[0]);
      await flush();
      assert.equal(el('error').textContent, NO_REPLY);
      assert.equal(el('room').childNodes.length, 0);
    });
  }
});

describe('list rendering', () => {
  test('renders one li per booking in reply order', async () => {
    const { calls, el, flush } = loadPage();
    calls[1].resolve(200, { bookings: [B1, B2] });
    await flush();
    const lis = el('booking-list').childNodes;
    assert.equal(lis.length, 2);
    const expected = [
      '2026-11-04 09:00-10:00 Cosmos: Standup',
      '2026-11-03 13:00-14:30 Aurora: <b>x</b>',
    ];
    lis.forEach((li, i) => {
      assert.equal(li.tagName, 'LI');
      assert.equal(li.childNodes.length, 2);
      assert.equal(li.childNodes[0].nodeType, 3);
      assert.equal(li.childNodes[0].data, expected[i]);
      const btn = li.childNodes[1];
      assert.equal(btn.tagName, 'BUTTON');
      assert.equal(btn.type, 'button');
      assert.equal(btn.textContent, 'Cancel');
      assert.equal(btn.disabled, false);
    });
  });

  test('title with surrounding spaces is shown unchanged', async () => {
    const { calls, el, flush } = loadPage();
    calls[1].resolve(200, { bookings: [{ ...B2, title: '  x  ' }] });
    await flush();
    assert.equal(el('booking-list').childNodes[0].childNodes[0].data,
      '2026-11-03 13:00-14:30 Aurora:   x  ');
  });

  test('empty reply shows a single No bookings. item', async () => {
    const { calls, el, flush } = loadPage();
    calls[1].resolve(200, { bookings: [] });
    await flush();
    const lis = el('booking-list').childNodes;
    assert.equal(lis.length, 1);
    assert.equal(lis[0].tagName, 'LI');
    assert.equal(lis[0].childNodes.length, 1);
    assert.equal(lis[0].childNodes[0].nodeType, 3);
    assert.equal(lis[0].childNodes[0].data, 'No bookings.');
  });
});

describe('list errors', () => {
  const cases = [
    ['error status with message', (c) => c.resolve(500, { error: 'date must be a valid YYYY-MM-DD date' }),
      'date must be a valid YYYY-MM-DD date'],
    ['404 without message', (c) => c.resolve(404, {}), FAILED],
    ['no reply', (c) => c.reject(), NO_REPLY],
    ['bad json on 200', (c) => c.resolveBadJson(200), NO_REPLY],
  ];
  for (const [name, act, message] of cases) {
    test(`${name} leaves the list as it was`, async () => {
      const page = loadPage();
      page.calls[1].resolve(200, { bookings: [B1] });
      await page.flush();
      await changeFilter(page, '2026-11-04');
      act(page.calls[2]);
      await page.flush();
      assert.equal(page.el('error').textContent, message);
      assert.deepEqual(texts(page), ['2026-11-04 09:00-10:00 Cosmos: Standup']);
    });
  }

  test('successful list fetch leaves #error alone', async () => {
    const { calls, el, flush } = loadPage();
    calls[0].resolve(500, { error: 'boom' });
    await flush();
    calls[1].resolve(200, { bookings: [B1] });
    await flush();
    assert.equal(el('error').textContent, 'boom');
  });
});

describe('overlapping list fetches', () => {
  test('(a) later fetch resolved first, earlier result ignored', async () => {
    const page = loadPage();
    await changeFilter(page, '2026-11-05');
    page.calls[2].resolve(200, { bookings: [X] });
    await page.flush();
    assert.deepEqual(texts(page), [X_TEXT]);
    page.calls[1].resolve(200, { bookings: [Y] });
    await page.flush();
    assert.deepEqual(texts(page), [X_TEXT]);
  });

  test('(b) earlier success while later pending changes nothing', async () => {
    const page = loadPage();
    await changeFilter(page, '2026-11-05');
    page.calls[1].resolve(200, { bookings: [Y] });
    await page.flush();
    assert.equal(page.el('booking-list').childNodes.length, 0);
    page.calls[2].resolve(200, { bookings: [X] });
    await page.flush();
    assert.deepEqual(texts(page), [X_TEXT]);
  });

  test('(c) earlier error status after later success leaves #error', async () => {
    const page = loadPage();
    await changeFilter(page, '2026-11-05');
    page.calls[2].resolve(200, { bookings: [X] });
    await page.flush();
    page.calls[1].resolve(500, { error: 'late' });
    await page.flush();
    assert.equal(page.el('error').textContent, '');
    assert.deepEqual(texts(page), [X_TEXT]);
  });

  test('(d) earlier reject after later success leaves #error', async () => {
    const page = loadPage();
    await changeFilter(page, '2026-11-05');
    page.calls[2].resolve(200, { bookings: [X] });
    await page.flush();
    page.calls[1].reject();
    await page.flush();
    assert.equal(page.el('error').textContent, '');
  });

