        }
        return v.bind(t);
      },
      set(t, prop, value) {
        accesses.push(`${kind}.${String(prop)}`);
        return Reflect.set(t, prop, value, t);
      },
    });
    targets.set(proxy, target);
    return proxy;
  }
  return { accesses, wrap, unwrap };
