function makeFetch(rec, calls) {
  return (url, options) => new Promise((resolve, reject) => {
    for (const key of Object.keys(options ?? {})) rec.accesses.push(`fetchOption.${key}`);
    const reply = (status, body) => resolve(rec.wrap('response', {
